with seed (slug, detail) as (
  values
    (
      'video-game-sales',
      $detail${"context":{"it":"Il mercato videoludico si estende su generazioni di console, generi e aree geografiche molto diverse. Leggere i soli volumi complessivi nasconde i cambiamenti che hanno modificato il settore nel tempo.","en":"The video game market spans console generations, genres and very different geographic areas. Looking only at total volumes hides the shifts that changed the industry over time."},"objective":{"it":"Individuare le piattaforme e i generi più rilevanti, confrontare il peso delle diverse regioni e osservare come le vendite si distribuiscono nelle principali epoche editoriali.","en":"Identify the most relevant platforms and genres, compare the weight of different regions and observe how sales are distributed across the main publishing eras."},"methodology":[{"id":"prepare","title":{"it":"Preparazione","en":"Preparation"},"description":{"it":"Controllo dei campi, gestione dei valori mancanti e normalizzazione di piattaforme, generi e aree geografiche.","en":"Field validation, missing-value handling and normalization of platforms, genres and geographic areas."}},{"id":"explore","title":{"it":"Esplorazione","en":"Exploration"},"description":{"it":"Aggregazione delle vendite per anno, piattaforma, genere e regione per rendere confrontabili dimensioni diverse.","en":"Sales aggregation by year, platform, genre and region to make different dimensions comparable."}},{"id":"compare","title":{"it":"Confronto","en":"Comparison"},"description":{"it":"Analisi delle quote regionali e dei cicli di vita delle piattaforme, con attenzione ai picchi e ai cambi di leadership.","en":"Analysis of regional shares and platform life cycles, focusing on peaks and leadership changes."}},{"id":"communicate","title":{"it":"Visualizzazione","en":"Visualization"},"description":{"it":"Sintesi dei risultati in KPI e viste progressive pensate per passare dal quadro generale al dettaglio.","en":"Results summarized through KPIs and progressive views designed to move from the big picture to detail."}}],"dataset":{"name":"Video Game Sales","source":{"it":"Dataset pubblico sulle vendite di videogiochi","en":"Public video game sales dataset"},"records":16598,"period":{"it":"1980–2016","en":"1980–2016"},"description":{"it":"Raccolta di titoli con anno di pubblicazione, piattaforma, genere, publisher e vendite espresse in milioni di copie per Nord America, Europa, Giappone e altre regioni.","en":"A collection of titles with release year, platform, genre, publisher and sales in millions of copies across North America, Europe, Japan and other regions."}},"insights":[{"id":"regional-mix","title":{"it":"Mercati con profili distinti","en":"Distinct market profiles"},"description":{"it":"Nord America ed Europa concentrano i volumi maggiori, mentre il Giappone mostra un mix di generi e piattaforme sensibilmente diverso.","en":"North America and Europe account for the largest volumes, while Japan shows a markedly different mix of genres and platforms."}},{"id":"platform-cycles","title":{"it":"Il peso dei cicli hardware","en":"The weight of hardware cycles"},"description":{"it":"Le vendite seguono cicli riconoscibili: crescita, picco e contrazione si ripetono al passaggio tra generazioni di console.","en":"Sales follow recognizable cycles: growth, peak and contraction repeat as console generations change."}},{"id":"genre-scale","title":{"it":"Pochi generi guidano la scala","en":"A few genres drive scale"},"description":{"it":"Action e Sports emergono per volume complessivo, ma il confronto regionale evidenzia preferenze meno uniformi di quanto suggerisca il totale globale.","en":"Action and Sports stand out by overall volume, but regional comparison reveals preferences that are less uniform than the global total suggests."}}],"updated_at":"2026-08-28"}$detail$::jsonb
    ),
    (
      'flight-analysis',
      $detail${"context":{"it":"Ritardi e cancellazioni influenzano passeggeri, aeroporti e compagnie lungo l'intera rete.","en":"Delays and cancellations affect passengers, airports and airlines across the entire network."},"objective":{"it":"Confrontare puntualità, rotte e fasce orarie per rendere visibili i principali driver operativi.","en":"Compare punctuality, routes and time windows to make the main operational drivers visible."},"methodology":[{"id":"clean","title":{"it":"Pulizia","en":"Cleaning"},"description":{"it":"Validazione di orari, aeroporti e stati del volo.","en":"Validation of times, airports and flight statuses."}},{"id":"segment","title":{"it":"Segmentazione","en":"Segmentation"},"description":{"it":"Confronto per rotta, vettore e fascia oraria.","en":"Comparison by route, carrier and time window."}},{"id":"explain","title":{"it":"Sintesi","en":"Synthesis"},"description":{"it":"KPI e visualizzazioni per isolare le aree critiche.","en":"KPIs and visualizations to isolate critical areas."}}],"dataset":{"name":"Flight Performance","source":{"it":"Dataset pubblico sulle performance dei voli","en":"Public flight performance dataset"},"description":{"it":"Voli, aeroporti, orari programmati ed effettivi, ritardi e cancellazioni.","en":"Flights, airports, scheduled and actual times, delays and cancellations."}},"insights":[{"id":"time","title":{"it":"L'orario conta","en":"Time matters"},"description":{"it":"La puntualità cambia sensibilmente tra le diverse fasce della giornata.","en":"On-time performance changes significantly across time windows."}},{"id":"routes","title":{"it":"Le rotte non sono equivalenti","en":"Routes are not equal"},"description":{"it":"Confronti omogenei fanno emergere corridoi con criticità ricorrenti.","en":"Like-for-like comparisons surface corridors with recurring issues."}}],"updated_at":"2026-07-20"}$detail$::jsonb
    ),
    (
      'listening-insights',
      $detail${"context":{"it":"Le abitudini di ascolto cambiano per momento, contenuto e frequenza.","en":"Listening habits change by moment, content and frequency."},"objective":{"it":"Tradurre gli eventi di ascolto in segnali leggibili su preferenze e continuità.","en":"Turn listening events into readable signals about preference and consistency."},"methodology":[{"id":"sessions","title":{"it":"Sessioni","en":"Sessions"},"description":{"it":"Raggruppamento degli eventi in sessioni coerenti.","en":"Grouping events into coherent sessions."}},{"id":"patterns","title":{"it":"Pattern","en":"Patterns"},"description":{"it":"Analisi di frequenza, durata e ricorrenza.","en":"Analysis of frequency, duration and recurrence."}},{"id":"story","title":{"it":"Racconto","en":"Story"},"description":{"it":"Sintesi visuale dei comportamenti più significativi.","en":"Visual synthesis of the most meaningful behaviors."}}],"dataset":{"name":"Listening History","source":{"it":"Esportazione anonimizzata degli ascolti","en":"Anonymized listening export"},"description":{"it":"Eventi anonimizzati con contenuto, timestamp e durata di riproduzione.","en":"Anonymized events with content, timestamp and playback duration."}},"insights":[{"id":"rhythm","title":{"it":"Ritmi ricorrenti","en":"Recurring rhythms"},"description":{"it":"Le sessioni evidenziano finestre di ascolto regolari durante la settimana.","en":"Sessions reveal regular listening windows throughout the week."}},{"id":"depth","title":{"it":"Frequenza e profondità","en":"Frequency and depth"},"description":{"it":"La ripetizione da sola non descrive il reale livello di coinvolgimento.","en":"Repetition alone does not describe the actual level of engagement."}}],"updated_at":"2026-06-12"}$detail$::jsonb
    ),
    (
      'stock-market-analysis',
      $detail${"context":{"it":"Prezzo e rendimento raccontano solo una parte del rischio di mercato.","en":"Price and return tell only part of the market-risk story."},"objective":{"it":"Confrontare trend, volatilità e comportamento relativo tra titoli e settori.","en":"Compare trends, volatility and relative behavior across securities and sectors."},"methodology":[{"id":"adjust","title":{"it":"Allineamento","en":"Alignment"},"description":{"it":"Uniformazione di calendari e serie temporali.","en":"Alignment of calendars and time series."}},{"id":"returns","title":{"it":"Rendimenti","en":"Returns"},"description":{"it":"Calcolo di variazioni, volatilità e drawdown.","en":"Calculation of changes, volatility and drawdowns."}},{"id":"benchmark","title":{"it":"Benchmark","en":"Benchmark"},"description":{"it":"Confronto relativo tra strumenti e settori.","en":"Relative comparison across instruments and sectors."}}],"dataset":{"name":"Market Time Series","source":{"it":"Estratto di dati storici di mercato","en":"Historical market data extract"},"description":{"it":"Serie storiche giornaliere di prezzo e volume per un paniere dimostrativo.","en":"Daily historical price and volume series for an illustrative basket."}},"insights":[{"id":"risk","title":{"it":"Rendimento senza contesto","en":"Return without context"},"description":{"it":"Performance simili possono nascondere profili di volatilità molto diversi.","en":"Similar performance can hide very different volatility profiles."}},{"id":"sector","title":{"it":"Dinamiche settoriali","en":"Sector dynamics"},"description":{"it":"Le fasi di mercato modificano la leadership relativa tra settori.","en":"Market phases change the relative leadership between sectors."}}],"updated_at":"2026-04-26"}$detail$::jsonb
    ),
    (
      'city-data-analysis',
      $detail${"context":{"it":"Gli indicatori urbani sono spesso frammentati tra servizi e periodi diversi.","en":"Urban indicators are often fragmented across different services and periods."},"objective":{"it":"Costruire una lettura comune di mobilità, servizi e qualità della vita.","en":"Build a shared view of mobility, services and quality of life."},"methodology":[{"id":"join","title":{"it":"Integrazione","en":"Integration"},"description":{"it":"Allineamento di fonti, aree e periodi.","en":"Alignment of sources, areas and periods."}},{"id":"normalize","title":{"it":"Normalizzazione","en":"Normalization"},"description":{"it":"Creazione di indicatori confrontabili.","en":"Creation of comparable indicators."}},{"id":"map","title":{"it":"Lettura territoriale","en":"Spatial view"},"description":{"it":"Confronto tra quartieri e servizi.","en":"Comparison across neighborhoods and services."}}],"dataset":{"name":"City Indicators","source":{"it":"Estratti di dati urbani pubblici","en":"Public urban data extracts"},"description":{"it":"Indicatori aggregati di mobilità, servizi e territorio per un prototipo in sviluppo.","en":"Aggregated mobility, service and spatial indicators for a work-in-progress prototype."}},"insights":[{"id":"access","title":{"it":"Accessibilità disomogenea","en":"Uneven accessibility"},"description":{"it":"La distanza dai servizi varia tra aree con caratteristiche simili.","en":"Distance to services varies across areas with similar characteristics."}}]}$detail$::jsonb
    ),
    (
      'sports-performance',
      $detail${"context":{"it":"Le statistiche sportive acquistano valore quando ruolo e minuti giocati sono confrontabili.","en":"Sports statistics become useful when role and minutes played are comparable."},"objective":{"it":"Creare confronti equilibrati tra atleti e leggere il contributo alla squadra.","en":"Create balanced comparisons between athletes and read their contribution to the team."},"methodology":[{"id":"roles","title":{"it":"Ruoli","en":"Roles"},"description":{"it":"Segmentazione per ruolo e utilizzo.","en":"Segmentation by role and usage."}},{"id":"rates","title":{"it":"Metriche relative","en":"Rate metrics"},"description":{"it":"Normalizzazione delle statistiche per tempo giocato.","en":"Normalization of statistics by playing time."}},{"id":"compare","title":{"it":"Confronto","en":"Comparison"},"description":{"it":"Profili multidimensionali per atleta e squadra.","en":"Multidimensional profiles by athlete and team."}}],"dataset":{"name":"Sports Performance","source":{"it":"Statistiche di gara anonimizzate","en":"Anonymized match statistics"},"description":{"it":"Statistiche di gara anonimizzate per atleti, ruoli e squadre.","en":"Anonymized match statistics for athletes, roles and teams."}},"insights":[{"id":"context","title":{"it":"Il contesto cambia il confronto","en":"Context changes the comparison"},"description":{"it":"Le metriche per minuto riducono l'effetto del diverso impiego.","en":"Per-minute metrics reduce the effect of different playing time."}}]}$detail$::jsonb
    )
)
insert into public.project_details (
  project_id,
  context,
  objective,
  methodology,
  dataset_summary,
  insights,
  updated_at
)
select
  projects.id,
  seed.detail -> 'context',
  seed.detail -> 'objective',
  seed.detail -> 'methodology',
  seed.detail -> 'dataset',
  seed.detail -> 'insights',
  coalesce((seed.detail ->> 'updated_at')::timestamptz, now())
from seed
join public.projects on projects.slug = seed.slug
on conflict (project_id) do update
set
  context = excluded.context,
  objective = excluded.objective,
  methodology = excluded.methodology,
  dataset_summary = excluded.dataset_summary,
  insights = excluded.insights,
  updated_at = excluded.updated_at;
